# Generated example games and an example database.
#
# No external game collection exists for this variant, so examples, tests
# and timing evidence use games generated by the engine under the installed
# rules profile: short search-versus-random and random games (a ply cap
# ends them with a `truncated` session event, which is never a rule draw)
# and hand-made fixtures that cover resignation, an agreed draw after the
# same moves, a takeback, a platform half-turn carrying a pawn to
# promotion, pieces on two physical squares with the same projected file
# and rank, checkmate and a live unfinished game. Every fixture is labelled
# as generated; ids and dates are fixed so repeated runs give the same
# games. No binary database is shipped: `.g3_example_game_db()` builds one.

.G3_EXAMPLE_DATE <- "2026-10-26T12:00:00.000Z"

# Play a game between built-in agents up to a ply cap.
#' @noRd
.g3_simulate_game <- function(white = "random", black = "random", max_plies = 8L, seed = 1L,
                              nodes = 50L, state = NULL, game_id = NULL, created = .G3_EXAMPLE_DATE) {
  players <- list(white = paste0(white, " (generated)"), black = paste0(black, " (generated)"))
  game <- if (is.null(state)) g3_new_game(players = players) else .g3_game_new(state, players = players)
  game$metadata$game_id <- game_id %||% game$metadata$game_id
  game$metadata$created <- created
  game$metadata$mode <- "simulation"
  game$metadata$agents <- list(white = list(agent = white), black = list(agent = black))
  game$provenance <- list(generator = "gambitR3D engine fixture", seed = as.integer(seed),
                          budget = list(nodes = as.integer(nodes)))
  agents <- c(white = white, black = black)
  for (i in seq_len(max_plies)) {
    if (g3_is_terminal(game$state)) break
    side <- game$state$side
    d <- g3_choose_action(game$state, agent = agents[[side]], budget = list(nodes = as.integer(nodes)),
                          seed = as.integer((as.numeric(seed) * 1009 + i) %% 2147483647))
    game <- g3_game_apply(game, d$action_id)
  }
  if (!g3_is_terminal(game$state)) game <- g3_game_event(game, "truncated", reason = "max_plies")
  game
}

#' @noRd
.g3_fixture_pieces <- function(...) {
  x <- strsplit(c(...), " ", fixed = TRUE)
  data.frame(id = vapply(x, `[`, "", 1L), type = vapply(x, `[`, "", 2L), color = vapply(x, `[`, "", 3L),
             square_id = vapply(x, `[`, "", 4L), stringsAsFactors = FALSE)
}

# A named list of generated example games (see the header).
#' @noRd
.g3_example_games <- function(seed = 20261026L, n_search = 2L, n_random = 2L, max_plies = 8L, nodes = 50L) {
  out <- list()
  label <- function(g, id, white, black, extra = list()) {
    g$metadata$game_id <- paste0("example-", id)
    g$metadata$created <- .G3_EXAMPLE_DATE
    g$metadata$players <- list(white = white, black = black)
    g$metadata$mode <- extra$mode %||% "fixture"
    g$provenance <- list(generator = "gambitR3D hand-made fixture", note = extra$note %||% NULL)
    g
  }
  play <- function(g, ids) {
    for (a in ids) g <- g3_game_apply(g, a)
    g
  }
  for (k in seq_len(n_search)) {
    colours <- if (k %% 2L) c("search", "random") else c("random", "search")
    out[[paste0("search_vs_random_", k)]] <- .g3_simulate_game(
      colours[1L], colours[2L], max_plies = max_plies, seed = seed + k, nodes = nodes,
      game_id = paste0("example-search-", k)
    )
  }
  for (k in seq_len(n_random)) {
    out[[paste0("random_", k)]] <- .g3_simulate_game(
      "random", "random", max_plies = max_plies, seed = seed + 100L + k, game_id = paste0("example-random-", k)
    )
  }
  opening <- c("m:W:0:1-W:0:2", "m:B:0:2-B:0:1")
  base <- play(g3_new_game(), opening)
  out$resign <- label(g3_game_event(base, "resign"), "resign", "Ada", "Ben")
  out$draw_agreed <- label(g3_game_event(base, "draw_agreed"), "draw-agreed", "Ada", "Ben",
                           list(note = "same moves as example-resign, different adjudication"))
  tb <- g3_game_event(play(g3_new_game(), c(opening, "m:W:1:1-W:1:2")), "takeback")
  out$takeback <- label(play(tb, "m:W:2:1-W:2:2"), "takeback", "Ada", "Ben", list(mode = "hotseat"))
  # A platform half-turn carrying a pawn onto its promotion rank, then the
  # promotion (see the format tests for the geometry).
  st <- g3_setup_position(.g3_fixture_pieces("wP P white WQ:0:1", "wK K white W:0:0", "bK K black B:3:3"),
                          docks = c(WQ = "N:L:hi", BQ = "N:R:hi"))
  out$platform_rotation <- label(play(.g3_game_new(st), c("t:WQ>B:L:hi@180", "m:B:3:3-B:2:3", "m:WQ:0:1-WQ:0:0=Q")),
                                 "platform-rotation", "Ada", "Ben",
                                 list(note = "set-up position; platform WQ turned through 180 degrees"))
  # W:1:2 and N:1:0 are different physical squares that project to the same
  # file and rank (c3).
  st <- g3_setup_position(.g3_fixture_pieces("wK K white W:0:0", "wN N white W:1:2", "bN N black N:1:0",
                                             "bK K black B:3:3"))
  out$overlap <- label(play(.g3_game_new(st), c("m:W:0:0-W:1:0", "m:B:3:3-B:2:3")), "overlap", "Ada", "Ben",
                       list(note = "set-up position; W:1:2 and N:1:0 share projected square c3"))
  st <- g3_setup_position(.g3_fixture_pieces("wK K white WK:0:0", "bQ Q black B:0:0", "bRd R black N:2:3",
                                             "bRf R black BK:1:1", "bK K black B:0:3"), side = "black")
  out$checkmate <- label(play(.g3_game_new(st), "m:B:0:0-B:3:0"), "checkmate", "Ada", "Ben",
                         list(note = "set-up position; mate in one"))
  out$live <- label(play(g3_new_game(), c(opening, "m:W:1:1-W:1:2")), "live", "Ada", "search",
                    list(mode = "computer"))
  out$live$metadata$agents <- list(white = "human", black = list(agent = "search", model_revision = NA))
  out
}

# Build an example database at `path` from the generated games.
#' @noRd
.g3_example_game_db <- function(path, games = .g3_example_games()) {
  db <- g3_open_game_db(path)
  on.exit(g3_close_game_db(db), add = TRUE)
  for (g in games) g3_save_game(db, g, source = "example")
  ids <- vapply(games, function(g) g$metadata$game_id, "")
  for (id in ids) g3_annotate_game(db, id, "generated example", kind = "tag")
  if ("example-platform-rotation" %in% ids) g3_annotate_game(db, "example-platform-rotation", "platform", kind = "tag")
  if ("example-checkmate" %in% ids) {
    g3_annotate_game(db, "example-checkmate", "The queen mates along the e-file.", ply = 1L, author = "fixture")
  }
  invisible(path)
}

# Write games as one JSONL collection (for import fixtures).
#' @noRd
.g3_write_jsonl <- function(games, path) {
  lines <- vapply(games, function(g) {
    as.character(jsonlite::toJSON(.g3_game_to_list(g), auto_unbox = TRUE, digits = NA, null = "null", na = "null"))
  }, "")
  .g3_atomic_write(paste0(paste(lines, collapse = "\n"), "\n"), path)
}
